import type { Editor } from "../../core/editor";
import {
  CopyDocument,
  Delete,
  Edit,
  RefreshLeft,
  RefreshRight,
  View,
} from "@element-plus/icons-vue";
/**
 * 顶部工具栏（预览/设计切换 + 撤销/重做 + 设备预设）
 */
import { defineComponent, PropType } from "vue";
import { useAssemNamespace } from "../../hooks/use-assem-namespace";

const ns = useAssemNamespace("toolbar");

export const EditorToolbar = defineComponent({
  name: "EditorToolbar",
  props: {
    editor: { type: Object as PropType<Editor>, required: true },
  },
  setup(props) {
    return () => {
      const store = props.editor.store;
      return (
        <div
          class={ns.b()}
          style={{
            "display": "flex",
            "flex-wrap": "nowrap",
            "align-items": "center",
            "gap": "6px",
            "padding": "0 12px",
            "width": "100%",
            "height": "100%",
            "overflow": "hidden",
          }}
        >
          {/* 设计/预览切换 */}
          <el-button-group>
            <el-button
              size="small"
              type={store.state.designMode === "design" ? "primary" : "default"}
              icon={Edit}
              onClick={() => {
                if (store.state.designMode !== "design") {
                  props.editor.setDesignMode("design");
                }
              }}
            >
              设计
            </el-button>
            <el-button
              size="small"
              type={
                store.state.designMode === "preview" ? "primary" : "default"
              }
              icon={View}
              onClick={() => {
                if (store.state.designMode !== "preview") {
                  props.editor.setDesignMode("preview");
                }
              }}
            >
              预览
            </el-button>
          </el-button-group>

          <el-divider direction="vertical" />

          {/* 撤销/重做 */}
          <el-button-group>
            <el-tooltip content="撤销 (Ctrl+Z)" placement="bottom">
              <el-button
                size="small"
                disabled={!store.canUndo}
                icon={RefreshLeft}
                onClick={() => props.editor.undo()}
              />
            </el-tooltip>
            <el-tooltip content="重做 (Ctrl+Y)" placement="bottom">
              <el-button
                size="small"
                disabled={!store.canRedo}
                icon={RefreshRight}
                onClick={() => props.editor.redo()}
              />
            </el-tooltip>
          </el-button-group>

          <el-divider direction="vertical" />

          {/* 节点操作（有选中时可用） */}
          {store.state.activeId && (
            <el-button-group>
              <el-tooltip content="复制 (Ctrl+D)" placement="bottom">
                <el-button
                  size="small"
                  icon={CopyDocument}
                  onClick={() => props.editor.duplicate(store.state.activeId!)}
                />
              </el-tooltip>
              <el-tooltip content="删除 (Delete)" placement="bottom">
                <el-button
                  size="small"
                  icon={Delete}
                  type="danger"
                  onClick={() => props.editor.remove(store.state.activeId!)}
                />
              </el-tooltip>
            </el-button-group>
          )}

          <div style={{ flex: 1 }} />

          {/* 右侧面板切换 */}
          <el-button size="small" link onClick={() => store.toggleRightPanel()}>
            {store.state.rightPanelVisible ? "隐藏面板" : "显示面板"}
          </el-button>
        </div>
      );
    };
  },
});
